<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, ApiError, type SetSummary, type PracticeQuestion, type Attempt } from '../lib/api'
import { message, user, registerIdentityGuard, notify } from '../lib/state'
import { draftKey, readDraft, writeDraft } from '../lib/drafts'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import AttemptResult from '../components/AttemptResult.vue'
const route=useRoute(), set=ref<SetSummary>(), questions=ref<PracticeQuestion[]>([]), answers=ref<Record<string,string>>({}), current=ref(0), loading=ref(true), error=ref(''), storageError=ref(''), busy=ref(false), confirm=ref(false), attempt=ref<Attempt>(), conflict=ref(false), resumed=ref(false)
const question=computed(()=>questions.value[current.value]), answered=computed(()=>questions.value.filter(q=>answers.value[q.id]?.trim()).length)
let key=''
const removeIdentityGuard=registerIdentityGuard(reason=>{
  if(reason==='confirm' && busy.value){notify('练习正在提交，请等待完成后切换账户');return false}
  if(!key||attempt.value)return true
  try{writeDraft(key,answers.value);return true}catch{storageError.value='浏览器无法保存草稿，请先保留作答再切换账户';return false}
})
onBeforeUnmount(removeIdentityGuard)
async function load(){loading.value=true;error.value='';try{const data=await api.practice(String(route.params.id));set.value=data.set;questions.value=data.questions;key=draftKey(user.value!.id,data.set.id,data.set.version);answers.value=readDraft(key,data.questions.map(q=>q.id));resumed.value=Object.keys(answers.value).length>0;conflict.value=false;current.value=0}catch(e){error.value=message(e)}finally{loading.value=false}}
watch(answers,()=>{if(!key||attempt.value)return;try{writeDraft(key,answers.value);storageError.value=''}catch{storageError.value='浏览器无法保存草稿，关闭页面可能丢失未提交作答'}},{deep:true,flush:'sync'})
async function submit(){if(!set.value)return;busy.value=true;error.value='';try{attempt.value=(await api.submit(set.value.id,set.value.version,answers.value)).attempt;confirm.value=false;try{localStorage.removeItem(key)}catch{}window.scrollTo({top:0,behavior:'smooth'})}catch(e){error.value=message(e);conflict.value=e instanceof ApiError&&e.status===409&&e.code!=='session_changed';confirm.value=false}finally{busy.value=false}}
function again(){attempt.value=undefined;answers.value={};load()}
onMounted(load)
</script>
<template><div class="page-container practice-page"><RouterLink :to="`/sets/${route.params.id}`" class="back-link"><Icon name="left"/>返回题集</RouterLink><div v-if="loading" class="loading">正在准备练习…</div><template v-else-if="attempt"><AttemptResult :attempt="attempt"/><div class="modal-actions"><RouterLink to="/history" class="button">查看学习记录</RouterLink><button class="button primary" @click="again">再练一次<Icon name="refresh"/></button></div></template><template v-else-if="set && question"><header class="page-heading"><div><span class="topic-label">专注练习</span><h1>{{set.title}}</h1><p>{{resumed?'已恢复当前版本的本地作答草稿':'先独立思考，提交后再查看参考答案和解析'}}</p></div><span class="practice-count">{{current+1}} <span>/ {{questions.length}}</span></span></header><div class="practice-grid"><section class="practice-card"><div class="progress-track"><span :style="{width:`${answered/questions.length*100}%`}"/></div><Transition name="page" mode="out-in"><div :key="question.id" class="practice-content"><span class="type-label">{{question.type==='single'?'单选题 · 选择一个答案':'简答题 · 提交后对照答案自评'}}</span><h2>{{question.prompt}}</h2><div v-if="question.type==='single'" class="practice-options"><label v-for="(option,i) in question.options" :key="i" :class="{chosen:answers[question.id]===option}"><input v-model="answers[question.id]" type="radio" :name="question.id" :value="option"/><span class="option-letter">{{String.fromCharCode(65+i)}}</span><span>{{option}}</span><Icon v-if="answers[question.id]===option" name="check"/></label></div><label v-else class="short-answer">你的回答<textarea v-model="answers[question.id]" rows="8" placeholder="尝试用自己的话说明思路…"/></label></div></Transition><div class="practice-navigation"><button class="button" :disabled="current===0" @click="current--"><Icon name="left"/>上一题</button><button v-if="current<questions.length-1" class="button primary" @click="current++">下一题<Icon name="right"/></button><button v-else class="button primary" @click="confirm=true">提交练习<Icon name="check"/></button></div></section><aside class="answer-sheet"><h3>答题卡</h3><p class="muted small">已作答 {{answered}} / {{questions.length}}</p><div class="question-dots"><button v-for="(q,i) in questions" :key="q.id" :class="{answered:!!answers[q.id]?.trim(),current:current===i}" :aria-label="`第 ${i+1} 题，${answers[q.id]?'已作答':'未作答'}`" :aria-current="current===i?'step':undefined" @click="current=i">{{i+1}}</button></div><p class="draft-note"><Icon name="check"/>作答自动保存在当前浏览器</p><p class="small muted">简答题不计入自动得分<br/>提交后可自行对照参考答案</p><button class="button primary" :disabled="busy" @click="confirm=true">提交练习</button></aside></div></template><p v-if="storageError" class="error" role="alert">{{storageError}}</p><div v-if="error" class="error" role="alert">{{error}}<button v-if="conflict" class="text-button" @click="load">题集已更新，载入新版本重新作答</button><button v-else-if="!set" class="text-button" @click="load">重试</button></div><div v-if="!loading&&set&&!questions.length" class="empty-state"><h2>这份题集还没有题目</h2><RouterLink :to="`/sets/${set.id}`" class="button">返回题集</RouterLink></div><Modal :open="confirm" title="提交本次练习" @close="!busy && (confirm=false)"><p>{{answered<questions.length?`还有 ${questions.length-answered} 道题未作答，未回答的单选题会计为错误。`:'所有题目都已作答，准备好查看结果了吗？'}}</p><p class="muted">提交后单选自动判分，简答对照参考答案自行评价。</p><div class="modal-actions"><button class="button" :disabled="busy" @click="confirm=false">继续作答</button><button class="button primary" :disabled="busy" @click="submit">{{busy?'正在提交…':'确认提交'}}</button></div></Modal></div></template>
